#!/bin/sh
# Cupola agent installer. One command, generated by the hub:
#   curl -fsSL <hub>/install.sh | sudo sh -s -- --hub <hub> --code <code> --node <id>
# Options: --relay <url> (expose through a Bolthole relay instead of a URL),
#          --advertise <url> (override the address the hub should poll),
#          --prefix <dir> (install prefix, default /usr/local/bin).
set -eu

HUB="@HUB@"
CODE=""
NODE=""
RELAY=""
ADVERTISE=""
PREFIX="/usr/local/bin"

while [ $# -gt 0 ]; do
  case "$1" in
    --hub) HUB="$2"; shift 2 ;;
    --code) CODE="$2"; shift 2 ;;
    --node) NODE="$2"; shift 2 ;;
    --relay) RELAY="$2"; shift 2 ;;
    --advertise) ADVERTISE="$2"; shift 2 ;;
    --prefix) PREFIX="$2"; shift 2 ;;
    *) echo "unknown option: $1" >&2; exit 2 ;;
  esac
done
[ -n "$CODE" ] || { echo "--code is required" >&2; exit 2; }
[ -n "$NODE" ] || NODE="$(hostname | tr 'A-Z' 'a-z' | tr -cd 'a-z0-9-' | cut -c1-24)"
[ -n "$NODE" ] || NODE="node"

OS="$(uname -s | tr 'A-Z' 'a-z')"
case "$(uname -m)" in
  x86_64|amd64) ARCH="amd64" ;;
  aarch64|arm64) ARCH="arm64" ;;
  *) echo "unsupported architecture: $(uname -m)" >&2; exit 1 ;;
esac

SUDO=""
if [ "$(id -u)" -ne 0 ]; then
  if [ -w "$PREFIX" ] || [ "$OS" = "darwin" ]; then SUDO=""; else SUDO="sudo"; fi
fi
BIN="$PREFIX/cupola"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

RELEASES="https://github.com/abcdlsj/cupola/releases/latest/download"
ASSET="cupola_${OS}_${ARCH}.tar.gz"

verify() {
  if command -v sha256sum >/dev/null 2>&1; then SUM="sha256sum -c"; else SUM="shasum -a 256 -c"; fi
  if [ -f "$TMP/checksums.txt" ]; then
    (cd "$TMP" && grep " $1\$" checksums.txt > "$1.sum" && $SUM "$1.sum" >/dev/null 2>&1) || {
      echo "checksum mismatch for $1" >&2; exit 1;
    }
  fi
}

if curl -fsSL "$RELEASES/$ASSET" -o "$TMP/$ASSET"; then
  echo "downloading cupola $OS/$ARCH from the latest release"
  curl -fsSL "$RELEASES/checksums.txt" -o "$TMP/checksums.txt" 2>/dev/null || true
  verify "$ASSET"
  tar -C "$TMP" -xzf "$TMP/$ASSET" cupola
  $SUDO install -m 0755 "$TMP/cupola" "$BIN"
else
  echo "no release asset for $OS/$ARCH; downloading from $HUB"
  curl -fsSL "$HUB/install/cupola?os=$OS&arch=$ARCH" -o "$TMP/cupola"
  $SUDO install -m 0755 "$TMP/cupola" "$BIN"
fi

if [ "$OS" = "darwin" ]; then
  CONF_DIR="$HOME/.config/cupola"
  SERVICE_DIR="$HOME/Library/LaunchAgents"
else
  CONF_DIR="/etc/cupola"
  SERVICE_DIR="/etc/systemd/system"
fi
CONF="$CONF_DIR/agent.json"
$SUDO mkdir -p "$CONF_DIR"
$SUDO chmod 700 "$CONF_DIR"

LISTEN="0.0.0.0:9797"
if [ -z "$ADVERTISE" ]; then
  if [ "$OS" = "darwin" ]; then
    IP="$(ipconfig getifaddr en0 2>/dev/null || ipconfig getifaddr en1 2>/dev/null || echo 127.0.0.1)"
  else
    IP="$(hostname -I 2>/dev/null | awk '{print $1}')"
    [ -n "$IP" ] || IP="$(ip route get 1.1.1.1 2>/dev/null | awk '{print $7; exit}')"
    [ -n "$IP" ] || IP="127.0.0.1"
  fi
  ADVERTISE="http://$IP:9797"
fi
if [ -n "$RELAY" ]; then
  LISTEN="127.0.0.1:9797"
  ADVERTISE=""
fi

if [ ! -f "$CONF" ]; then
  $SUDO "$BIN" agent --init --node "$NODE" --name "$NODE" --config "$CONF" >/dev/null
fi

JOIN_ARGS="--join $HUB --join-code $CODE --advertise $ADVERTISE"
[ -n "$RELAY" ] && JOIN_ARGS="--join $HUB --join-code $CODE --relay $RELAY"

if [ "$OS" = "darwin" ]; then
  PLIST="$SERVICE_DIR/com.cupola.agent.plist"
  mkdir -p "$SERVICE_DIR"
  cat > "$PLIST" <<PLISTEOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>com.cupola.agent</string>
  <key>ProgramArguments</key><array>
    <string>$BIN</string><string>agent</string><string>--config</string><string>$CONF</string>
    <string>--listen</string><string>$LISTEN</string>
    $(echo "$JOIN_ARGS" | tr ' ' '\n' | sed 's/.*/<string>&<\/string>/' | tr '\n' ' ')
  </array>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
</dict></plist>
PLISTEOF
  launchctl unload "$PLIST" 2>/dev/null || true
  launchctl load "$PLIST"
  LOG="$HOME/Library/Logs/cupola-agent.log"
  mkdir -p "$(dirname "$LOG")"
else
  UNIT="$SERVICE_DIR/cupola-agent.service"
  cat > "$UNIT" <<UNITEOF
[Unit]
Description=Cupola agent
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=$BIN agent --config $CONF --listen $LISTEN $JOIN_ARGS
Restart=on-failure
RestartSec=3
NoNewPrivileges=true
PrivateTmp=true

[Install]
WantedBy=multi-user.target
UNITEOF
  chmod 600 "$UNIT"
  systemctl daemon-reload
  systemctl enable --now cupola-agent
  LOG="journalctl -u cupola-agent -n 20 --no-pager"
fi

echo
echo "waiting for the hub to confirm the join..."
for _ in $(seq 1 20); do
  sleep 1
  LINK=$($LOG 2>/dev/null | grep -o 'open: http[^ ]*' | head -1 | sed 's/^open: //')
  if [ -n "$LINK" ]; then
    echo "joined: $LINK"
    echo
    echo "The agent is running and the hub starts polling it now."
    exit 0
  fi
done
echo "The agent started but the hub has not confirmed yet. Check:"
echo "  $LOG"
exit 1
